import type { BreakerState } from '../breaker';
import type { IntegrationStatus, PausedReason } from '../integration-status';
import type { ProviderName } from '../normalise';
import type { IntegrationRecord, ListPage, PageQuery } from './records';

export const INTEGRATION_REPOSITORY = Symbol('INTEGRATION_REPOSITORY');

export interface InsertConnectedInput {
  /** Generated by the caller: the credentials are sealed with context `integration:<id>` before the insert. */
  id: string;
  shopId: string;
  provider: ProviderName;
  externalShop: string;
  credentialsSealed: string;
  locationId: string | null;
  connectedBy: string;
  now: Date;
  /** Per-shop limit of non-DISCONNECTED integrations (5). */
  maxPerShop: number;
}

export type InsertConnectedResult =
  | { kind: 'inserted'; integration: IntegrationRecord }
  | { kind: 'store_already_connected' }
  | { kind: 'limit_reached' };

export interface TransitionOptions {
  /** Free text kept in the history row (e.g. the action name). */
  reason: string;
  actorId: string | null;
  now: Date;
  pausedReason?: PausedReason | null;
  /** Reconnect: new sealed credentials (and location). */
  credentialsSealed?: string;
  locationId?: string | null;
  lastError?: string | null;
  /** Disconnect: null the sealed credentials. */
  eraseCredentials?: boolean;
}

export interface IntegrationRepository {
  /**
   * Under `pg_advisory_xact_lock('integration-limit:' || shopId)`: counts the shop's non-DISCONNECTED rows, inserts the
   * ACTIVE row and a history row. Joins the caller's transaction.
   */
  insertConnected(input: InsertConnectedInput): Promise<InsertConnectedResult>;
  /**
   * Conditional `UPDATE ... WHERE id AND status = :from RETURNING` plus the history row, in one transaction. `null` =
   * the row was not in `from` (refused or lost a race): nothing written, the caller emits no event.
   */
  transition(
    id: string,
    from: IntegrationStatus,
    to: IntegrationStatus,
    options: TransitionOptions,
  ): Promise<IntegrationRecord | null>;
  /**
   * `pg_advisory_xact_lock('integration-limit:' || shopId)` in the caller's transaction: serialises the connects of one
   * shop (a reconnect of a DISCONNECTED row counts toward the limit again). Requires an active transaction.
   */
  lockShopLimit(shopId: string): Promise<void>;
  findById(id: string): Promise<IntegrationRecord | null>;
  /** Shop and ID in one predicate; another shop's row is indistinguishable from a missing one. */
  findInShop(shopId: string, id: string): Promise<IntegrationRecord | null>;
  /** The shop's row for this store in any status (used to reuse a DISCONNECTED row on reconnect). */
  findByShopAndStore(
    shopId: string,
    provider: ProviderName,
    externalShop: string,
  ): Promise<IntegrationRecord | null>;
  /** The non-DISCONNECTED row of a store (webhook resolution). */
  findLiveByStore(
    provider: ProviderName,
    externalShop: string,
  ): Promise<IntegrationRecord | null>;
  /** `(createdAt DESC, id DESC)` keyset page of the shop's integrations, any status. */
  listPage(
    shopId: string,
    query: PageQuery,
  ): Promise<ListPage<IntegrationRecord>>;
  listByShop(
    shopId: string,
    statuses: readonly IntegrationStatus[],
  ): Promise<IntegrationRecord[]>;
  /** Non-DISCONNECTED rows of the shop (the per-shop limit counts these). */
  countActiveForShop(shopId: string): Promise<number>;
  /** ACTIVE rows whose `nextSyncAt` is null or <= now, oldest first. */
  dueForSync(
    now: Date,
    limit: number,
  ): Promise<
    Array<
      Pick<IntegrationRecord, 'id' | 'shopId' | 'provider' | 'breakerOpenUntil'>
    >
  >;
  /** ACTIVE rows, keyset by id (the nightly reconciliation pass). */
  listActive(
    afterId: string | null,
    limit: number,
  ): Promise<
    Array<
      Pick<IntegrationRecord, 'id' | 'shopId' | 'provider' | 'breakerOpenUntil'>
    >
  >;
  /** ACTIVE rows that have a product watermark, keyset by id (lag evaluation). */
  activeWatermarks(
    afterId: string | null,
    limit: number,
  ): Promise<
    Array<
      Pick<IntegrationRecord, 'id' | 'shopId' | 'provider'> & {
        watermark: Date;
      }
    >
  >;
  /** Number of non-DISCONNECTED integrations whose breaker is open at `now`, per provider (the breaker gauge). */
  countBreakerOpen(now: Date): Promise<Record<string, number>>;
  setNextSync(id: string, at: Date | null): Promise<void>;
  /** After a completed pass: `lastSyncAt`, `nextSyncAt`, clears `lastError`. */
  recordSynced(id: string, at: Date, nextSyncAt: Date | null): Promise<void>;
  recordError(id: string, message: string): Promise<void>;
  /** Re-seals refreshed credentials (OAuth refresh); only while the row is not DISCONNECTED. */
  updateCredentials(id: string, credentialsSealed: string): Promise<boolean>;
  /** Breaker state as stored (`consecutiveFailures`, `breakerOpenUntil`). */
  loadBreaker(id: string): Promise<BreakerState | null>;
  saveBreaker(id: string, state: BreakerState): Promise<void>;
  /**
   * Atomic read-modify-write of the breaker columns under a row lock (`SELECT ... FOR UPDATE`): the one caller that
   * wins the probe after the open period is decided here (AS-59). The step returns the state to store.
   */
  updateBreaker<T>(
    id: string,
    step: (current: BreakerState) => { state: BreakerState; result: T },
    /** Runs in the same transaction after the update (the outbox event of an opened breaker). */
    inTransaction?: (result: T) => Promise<void>,
  ): Promise<T>;
}
